// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(70000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/cart`);
    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await page.getByRole("button", { name: "Add To Cart" }).click();
    await expect(page.getByText("Sunglasses × 1 — $")).toContainText("Sunglasses × 1 — $19.99");
    await expect(page.locator("#email-preview-panel .preview-total")).toHaveText("$28.98");
    await expect(page.locator(".cart-summary-total-row")).toContainText("$28.98");

    const money = (t: string) => parseFloat(t.replace(/[^0-9.]/g, ""));
    const previewTotal = money(await page.locator("#email-preview-panel .preview-total").innerText());
    const cartTotal = money(await page.locator(".cart-summary-total-row .text-right").innerText());
    const shipping = money(await page.locator(".cart-summary-shipping-row .text-right").innerText());
    const previewItems = money((await page.locator("#email-preview-panel .preview-items div").first().innerText()).split("—")[1]);
    expect(previewTotal).toBe(cartTotal);
    expect(previewTotal).toBeCloseTo(previewItems + shipping, 2);
});
